<?php defined('ABSPATH') || exit;
$kind=in_array($values['kind']??'',array('photo','journal','video'),true)?$values['kind']:'photo';
$operation=$deleting?'delete_moment':($editing?'update_moment':'create_moment');
$nonce_id=$moment?$moment['id']:$pet['id'];
?>
<a class="pp-back" href="<?php echo esc_url(self::url()); ?>"><?php echo self::icon('arrow'); ?><?php esc_html_e('Back to My Pets','petish-passport'); ?></a>
<header class="pp-page-heading pc-heading"><div><p class="pp-eyebrow"><?php echo esc_html($pet['name'].' · '.__('Petish Passport','petish-passport')); ?></p><h2><?php echo esc_html($deleting?__('Keep the memories that matter.','petish-passport'):($editing?__('A little update to their story.','petish-passport'):('journal'===$kind?__('A new chapter, however small.','petish-passport'):__('A little moment worth keeping.','petish-passport')))); ?></h2><p class="pp-intro"><?php echo esc_html($deleting?__('Remove this moment from the active site. This cannot be undone here.','petish-passport'):__('Your moments stay private until you choose to share them.','petish-passport')); ?></p></div></header>
<form class="pp-form pp-panel pc-moment-form" method="post" enctype="multipart/form-data" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" data-pp-form><input type="hidden" name="action" value="petish_passport_<?php echo esc_attr($operation); ?>"><input type="hidden" name="pet_id" value="<?php echo esc_attr($pet['id']); ?>"><input type="hidden" name="moment_id" value="<?php echo esc_attr($moment['id']??0); ?>"><input type="hidden" name="kind" value="<?php echo esc_attr($kind); ?>"><?php wp_nonce_field('petish_passport_'.$operation.'_'.$nonce_id,'petish_passport_nonce'); ?>
<?php if($moment&&!empty($moment['photo'])): ?><img class="pc-form-photo" src="<?php echo esc_url(Petish_Passport_Moments::url($moment['id'],$moment['updated'])); ?>" alt="<?php esc_attr_e('Current private moment photo','petish-passport'); ?>" width="480" height="480"><?php endif; ?>
<?php if($moment&&!empty($moment['video'])): ?><div class="pc-form-video"><?php echo self::video(Petish_Passport_Moments::video_url($moment['id'],$moment['updated']),$moment['caption']); ?><p class="pp-field-hint"><?php echo esc_html(sprintf(__('Current private video · %s','petish-passport'),self::duration_label($moment['duration']??0))); ?></p></div><?php endif; ?>
<?php if($deleting): ?><p><?php echo esc_html($moment['caption']); ?></p><p class="pp-small"><?php esc_html_e('Removing a moment also turns off this pet’s public profile. You can publish a new selection afterwards.','petish-passport'); ?></p><label class="pp-checkbox"><input type="checkbox" name="confirm_delete" value="1" required><span><?php esc_html_e('Permanently remove this moment and its stored media.','petish-passport'); ?></span></label>
<?php else: ?>
<?php if('photo'===$kind): ?><div class="pp-field"><label for="pp-photo"><?php echo esc_html($editing?__('Replace photo (optional)','petish-passport'):__('Moment photo','petish-passport')); ?></label><input type="file" id="pp-photo" name="photo" accept="image/jpeg,image/png,image/webp" <?php if(!$editing) echo 'required'; ?> aria-describedby="pp-photo-help pp-photo-feedback" data-pp-photo><p class="pp-field-hint" id="pp-photo-help"><?php esc_html_e('JPEG, PNG or WebP, up to 5 MB and 16 megapixels.','petish-passport'); ?></p><p class="pp-field-hint" id="pp-photo-feedback" aria-live="polite" data-pp-photo-feedback></p></div><?php endif; ?>
<?php if('video'===$kind): ?><div class="pp-field"><label for="pp-video"><?php echo esc_html($editing?__('Replace video (optional)','petish-passport'):__('Moment video','petish-passport')); ?></label><input type="file" id="pp-video" name="video" accept="video/mp4,.mp4" <?php if(!$editing)echo 'required'; ?> aria-describedby="pp-video-help pp-video-feedback" data-pp-video><p class="pp-field-hint" id="pp-video-help"><?php esc_html_e('MP4 with H.264 video and optional AAC audio. Up to 20 seconds and 20 MB.','petish-passport'); ?></p><p class="pp-field-hint" id="pp-video-feedback" aria-live="polite" data-pp-video-feedback></p><div class="pc-form-video" data-pp-video-preview hidden><p class="pp-field-hint"><?php esc_html_e('Selected video · not saved yet','petish-passport'); ?></p><video class="pc-moment-video" controls playsinline preload="metadata" aria-label="<?php esc_attr_e('Preview of selected video','petish-passport'); ?>"></video></div></div><p class="pp-small"><?php esc_html_e('Videos may retain location or device information. Choose a clip you’re comfortable sharing before you publish it.','petish-passport'); ?></p><?php endif; ?>
<div class="pp-field"><label for="pc-moment-caption"><?php echo esc_html('journal'===$kind?__('Your journal entry','petish-passport'):__('A little caption (optional)','petish-passport')); ?></label><textarea id="pc-moment-caption" name="caption" maxlength="240" rows="5" <?php if('journal'===$kind)echo 'required'; ?> aria-describedby="pc-caption-help"><?php echo esc_textarea($values['caption']??''); ?></textarea><p id="pc-caption-help" class="pp-field-hint"><?php esc_html_e('Up to 240 characters. A little detail can hold a big memory.','petish-passport'); ?></p></div>
<?php if($editing): ?><p class="pc-inline-note"><?php echo self::icon('lock'); ?><?php esc_html_e('Published details stay as they were until you update sharing. Replacing a photo or video turns sharing off for this pet.','petish-passport'); ?></p><?php endif; ?>
<?php endif; ?><div class="pp-form-actions"><button type="submit" class="pp-button <?php if($deleting)echo 'pp-button-danger'; ?>"><?php echo esc_html($deleting?__('Remove moment','petish-passport'):($editing?__('Save changes','petish-passport'):__('Save privately','petish-passport'))); ?></button><a class="pp-cancel" href="<?php echo esc_url(self::url()); ?>"><?php esc_html_e('Cancel','petish-passport'); ?></a></div></form>
<?php if($editing): ?><div class="pp-delete-link"><a href="<?php echo esc_url(self::moment_url('moment-delete',$pet['id'],$moment['id'],$kind)); ?>"><?php esc_html_e('Remove this moment','petish-passport'); ?></a></div><?php endif; ?>
